-- Manually generated

local register, pairs, mapper, commitapply, find, sub = register, pairs, mapper, commitapply, string.find, string.sub
local uciHelper = mapper("ucihelper")
local bandSteerHelper = require("transformer.shared.bandsteerhelper")
local setSecurityOption = bandSteerHelper.setSecurityOption
local setOnUci =  uciHelper.set_on_uci
local forEachOnUci = uciHelper.foreach_on_uci
local getFromUci = uciHelper.get_from_uci
local wirelessBinding = { config = "wireless" }
local multiapBinding = { config = "multiap" }
local multiapControllerBinding = {config='multiap', sectionname='controller', option='enabled'}
local multiapAgentBinding = {config='multiap', sectionname='agent', option='enabled'}
local crypto = require("tch.simplecrypto")
local transactions = {}
local knownPrefix = "Ngarigo"

local Device_WiFi_X_TELSTRA_WiFi_ = {
  objectType = {
    name = "Device.WiFi.X_TELSTRA_WiFi.",
    access = "readOnly",
